import {ingredients} from './cafe-content.mjs';
import {foodArt,qualityIcons,hearButton} from './play-media.mjs';
import {ensureCafe,availableIngredients,setCafeRange,repairQuestion,answerRepair,helpRepair,leaveRepair,orderFor,currentRecipe,checkPlate,reviseCafePlate,adjustBite,submitCafeNumber,supportCafe,skipCafeStage,serveCafe,nextGuest,skipGuest,cafeSummary,cafeSupper,beginCafePlus} from './cafe-core.mjs';
import {numericAnswer} from './core.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const plural=(n,word)=>`${n} ${word}${n===1?'':'s'}`;
const action=(id,label,style='secondary',extra='')=>`<button type="button" class="${style}" data-cafe-action="${id}" ${extra}>${label}</button>`;
const tags=properties=>qualityIcons(properties);
const dots=(count,color)=>Array.from({length:count},()=>`<span class="cafe-bite" style="--bite:${esc(color)}" aria-hidden="true"></span>`).join('');

function guestArt(guest){
 const kittenCoat=guest.id==='biscuit'?'#e5a36f':'#abc4da';
 const silhouettes={
  'kitten':`<path d="M139 153q46 12 32-28" fill="none" stroke="${kittenCoat}" stroke-width="14" stroke-linecap="round"/><ellipse cx="101" cy="145" rx="39" ry="33" fill="${kittenCoat}"/><ellipse cx="101" cy="150" rx="23" ry="24" fill="#fff8e9"/><path d="m55 90 2-48 34 26q12-4 24 0l32-26 1 50" fill="${kittenCoat}" stroke="#183f39" stroke-width="2"/><path d="m64 72 1-13 15 15m45 0 14-15 1 15" fill="#da8d8d"/><ellipse cx="101" cy="101" rx="47" ry="37" fill="${kittenCoat}"/><path d="m89 69 4 13m8-15v14m11-12-4 13" stroke="#183f39" stroke-width="3" opacity=".4"/><ellipse cx="77" cy="172" rx="22" ry="9" fill="${kittenCoat}"/><ellipse cx="125" cy="172" rx="22" ry="9" fill="${kittenCoat}"/><path d="m96 110 5 5 5-5Z" fill="#da8d8d"/><path d="m69 113-24-5m24 12-25 4m89-11 24-5m-24 12 25 4" stroke="#183f39" stroke-width="2" stroke-linecap="round"/>`,
  'bunny':'<ellipse cx="74" cy="46" rx="16" ry="39" fill="#f3ead9" stroke="#183f39" stroke-width="2"/><ellipse cx="124" cy="43" rx="16" ry="39" fill="#f3ead9" stroke="#183f39" stroke-width="2"/><ellipse cx="74" cy="43" rx="7" ry="26" fill="#da8d8d"/><ellipse cx="124" cy="40" rx="7" ry="26" fill="#da8d8d"/><circle cx="152" cy="149" r="17" fill="#fffef9" stroke="#183f39" stroke-width="2"/><ellipse cx="100" cy="145" rx="45" ry="34" fill="#f3ead9"/><ellipse cx="100" cy="102" rx="49" ry="43" fill="#f3ead9"/><ellipse cx="74" cy="173" rx="24" ry="9" fill="#f3ead9"/><ellipse cx="126" cy="173" rx="24" ry="9" fill="#f3ead9"/><path d="m97 111 5 5 5-5Z" fill="#da8d8d"/><path d="m70 116-23-4m24 10-25 4m88-10 23-4m-24 10 25 4" stroke="#183f39" stroke-width="2"/>',
  'pocket-dragon':'<path d="M54 139Q9 126 21 61l35 23 6-31 23 50M140 139q49-20 40-78l-35 23-5-31-23 50" fill="#e9b84a" stroke="#397958" stroke-width="3"/><path d="M62 146Q14 142 22 168q8 18 30-2" fill="none" stroke="#90b9ae" stroke-width="15"/><ellipse cx="102" cy="142" rx="43" ry="34" fill="#90b9ae"/><ellipse cx="102" cy="149" rx="26" ry="25" fill="#eaf4ef"/><path d="m67 77-6-30 25 17m31 0 26-17-7 33" fill="#e9b84a" stroke="#397958" stroke-width="2"/><path d="M52 98Q50 63 94 61q52-4 55 39l-7 31q-37 25-78 0Z" fill="#90b9ae"/><path d="m90 64 12-23 13 24" fill="#397958"/><ellipse cx="75" cy="172" rx="22" ry="9" fill="#90b9ae"/><ellipse cx="128" cy="172" rx="22" ry="9" fill="#90b9ae"/>',
  'cloud-dragon':'<path d="M41 137Q10 106 39 91Q31 63 59 65Q68 29 91 56Q114 33 130 59Q169 49 163 83Q192 97 168 124L168 156H39Z" fill="#abc4da"/><path d="M44 118Q5 128 20 158Q30 173 42 154M143 139l18 29M68 140l-5 27" fill="none" stroke="#abc4da" stroke-width="16"/><path d="M64 63L57 41 79 53M122 59L139 39 136 69" fill="#e9b84a"/>',
  'umbrella-sprite':'<path d="M24 83Q100-20 176 83Q153 65 140 87Q120 68 100 88Q79 68 60 87Q45 65 24 83" fill="#da8d8d"/><path d="M100 75V159Q100 181 81 171" fill="none" stroke="#183f39" stroke-width="6"/><ellipse cx="100" cy="112" rx="39" ry="29" fill="#e9b84a"/>',
  'ribbon-giant':'<path d="M73 169Q36 136 64 108Q110 70 56 33Q105 19 126 53Q145 77 112 106Q82 136 133 169Z" fill="#da8d8d"/><path d="M54 61Q12 20 27 84L61 76M131 59Q178 17 169 85L127 77" fill="#e9b84a"/><ellipse cx="98" cy="94" rx="34" ry="29" fill="#f2d8b4"/>',
  'pebble-troll':'<path d="M35 154L30 101 52 49 107 30 153 60 174 117 155 161Z" fill="#90b9ae"/><path d="M45 153L39 177M143 155l11 22" stroke="#90b9ae" stroke-width="18"/><path d="M62 54L51 28 87 42M124 45l27-15-6 34" fill="#e9b84a"/>',
  'lantern-sprite':'<path d="M59 65H141L158 149Q100 178 42 149Z" fill="#e9b84a"/><path d="M66 58Q100 11 134 58" fill="none" stroke="#183f39" stroke-width="6"/><path d="M52 67H148M45 148H155" stroke="#397958" stroke-width="8"/><path d="M100 74V152" stroke="#fffef9" stroke-width="22" opacity=".5"/>',
  'little-comet':'<path d="M68 128Q8 102 15 34Q63 74 126 59L143 111Z" fill="#e9b84a"/><path d="M71 94Q45 73 45 56" stroke="#fffef9" stroke-width="7" fill="none"/><circle cx="113" cy="112" r="52" fill="#da8d8d"/>',
  'teacup-sprite':'<path d="M52 81H146L137 141Q100 166 64 141Z" fill="#b8d4c3"/><path d="M144 92Q188 80 174 119Q164 139 141 130" stroke="#b8d4c3" stroke-width="12" fill="none"/><ellipse cx="99" cy="66" rx="62" ry="13" fill="#da8d8d"/><ellipse cx="99" cy="60" rx="33" ry="13" fill="#e9b84a"/>',
  'star-sprite':'<path d="M100 25L119 69 169 69 137 108 152 161 100 137 49 161 63 108 30 69 81 69Z" fill="#e9b84a"/><path d="M49 163L38 177M149 162l13 16" stroke="#183f39" stroke-width="5"/>'
 };
 return `<svg class="cafe-guest-art" viewBox="0 0 200 200" role="img" aria-label="${esc(guest.name)}, an imaginary ${esc(guest.kind.replaceAll('-',' '))}"><ellipse cx="100" cy="181" rx="72" ry="9" fill="#183f39" opacity=".08"/>${silhouettes[guest.kind]||silhouettes['star-sprite']}<circle cx="85" cy="102" r="4" fill="#183f39"/><circle cx="117" cy="102" r="4" fill="#183f39"/><path d="M90 120Q101 130 113 119" fill="none" stroke="#183f39" stroke-width="3" stroke-linecap="round"/><circle cx="74" cy="115" r="7" fill="#da8d8d" opacity=".5"/><circle cx="128" cy="115" r="7" fill="#da8d8d" opacity=".5"/></svg>`;
}
function plateView(c,order){
 const selected=currentRecipe(c).flatMap(item=>Array.from({length:item.count},()=>item.ingredient));
 return `<div class="cafe-plate" role="img" aria-label="Your plate: ${esc(selected.map(a=>a.name).join(', ')||'empty')}; ${selected.length} of ${order.bites} bites"><div class="cafe-plate-inner">${Array.from({length:order.bites},(_,i)=>selected[i]?`<span class="cafe-slot filled" style="--bite:${esc(selected[i].color)}">${foodArt(selected[i].id)}<span class="cafe-slot-name">${esc(selected[i].name)}</span></span>`:'<span class="cafe-slot"><span aria-hidden="true">+</span><span class="cafe-slot-name">An empty spot</span></span>').join('')}</div></div>`;
}
function supperArt(goal){
 const color=goal.theme.color;
 const ornament=(x,lit)=>{const fill=lit?color:'#fffef9';const shape=goal.theme.decoration==='stars'?`<path d="m${x} 12 5 10 11 2-8 8 2 11-10-5-10 5 2-11-8-8 11-2Z" fill="${fill}"/>`:goal.theme.decoration==='leaves'?`<path d="M${x} 43q-24-20 0-32q24 12 0 32Zm0-23v21" fill="${fill}"/>`:goal.theme.decoration==='ribbons'?`<path d="M${x-10} 13h20v32l-10-7-10 7Z" fill="${fill}"/>`:`<path d="M${x-10} 17h20v22h-20Z" fill="${fill}"/><path d="M${x-5} 17v-6h10v6M${x} 20v16"/>`;return `<g stroke="#183f39" stroke-width="2" stroke-linejoin="round">${shape}</g>`;};
 return `<svg class="cafe-supper-art" viewBox="0 0 520 190" aria-hidden="true"><path d="M20 176H500" stroke="#183f39" stroke-width="3"/><path d="M60 174V80h400v94" fill="#fffef9" stroke="#183f39" stroke-width="3"/><path d="m43 80 28-29h378l28 29Z" fill="${color}" stroke="#183f39" stroke-width="3"/><path d="M78 102h82v48H78Zm282 0h82v48h-82Z" fill="${goal.complete?color:'#eaf4ef'}" stroke="#183f39" stroke-width="3"/><path d="M119 103v47m282-47v47M78 126h82m200 0h82" stroke="#183f39" stroke-width="2"/><rect x="192" y="96" width="136" height="62" rx="8" fill="${color}" stroke="#183f39" stroke-width="3"/><text x="260" y="133" text-anchor="middle" font-family="Trebuchet MS,sans-serif" font-size="${goal.complete?25:16}" font-weight="bold" fill="#183f39">${goal.complete?'OPEN':'ALMOST READY'}</text><path d="M42 10Q260 39 478 10" fill="none" stroke="#183f39" stroke-width="2"/>${Array.from({length:6},(_,i)=>ornament(80+i*72,i<goal.progress)).join('')}<path d="M35 175q-9-24 5-34q16 9 9 34m428 0q-8-24 6-34q15 9 9 34" fill="#90b9ae" stroke="#183f39" stroke-width="2"/></svg>`;
}
function supperPanel(c){
 const goal=cafeSupper(c),label=goal.round===1?'Our café goal':`New Game Plus ${goal.round-1}`;
 return `<section class="cafe-supper ${goal.complete?'cafe-supper-complete':''}" aria-labelledby="cafe-supper-title">${supperArt(goal)}<div><p class="cafe-eyebrow">${label}</p><h2 id="cafe-supper-title" tabindex="-1">${goal.complete?'You did it! ':''}${esc(goal.theme.title)}</h2><p${goal.complete?' role="status"':''}>${esc(goal.complete?goal.theme.ending:goal.theme.invitation)}</p><p class="cafe-supper-progress">${goal.progress} of ${goal.target} tables served${goal.complete?' · All six tables are ready!':''}</p>${goal.complete?`<div class="cafe-controls">${action('new-game-plus','New Game Plus: another gathering','primary')}${action('continue-cafe','Keep serving','secondary')}</div><p class="tiny">Another six-table adventure is waiting. Your cupboard, discoveries, and café work come with you.</p>`:'<p class="tiny">Each table you serve lights a decoration. Help and second tries are always welcome.</p>'}${hearButton(goal.complete?`${goal.theme.ending} You can start New Game Plus for another gathering, or keep serving.`:`${goal.theme.invitation} ${goal.progress} of six tables served. Help and second tries are always welcome.`,'Hear our café goal')}</div></section>`;
}
function plateEditor(c,summary){
 const items=summary.items;
 return `<section class="cafe-plate-editor" aria-labelledby="cafe-plate-editor-title"><h3 id="cafe-plate-editor-title" tabindex="-1">Change the bites on your plate</h3><p class="tiny">${summary.count>=summary.order.bites?'Your plate is full. Remove a bite to make room for something different.':items.length?'There is room for another bite. Choose an ingredient from the cupboard.':'Your plate is empty. Choose an ingredient from the cupboard.'}</p>${items.length?`<ul class="cafe-chosen-bites">${items.map(item=>`<li>${foodArt(item.ingredient.id)}<div><strong>${esc(item.ingredient.name)}</strong><span>${plural(item.count,'bite')} on your plate</span>${qualityIcons(item.ingredient.properties)}</div><button type="button" class="secondary" data-cafe-plate-remove="${item.ingredient.id}" aria-label="Take one ${esc(item.ingredient.name)} off the plate">Remove one</button></li>`).join('')}</ul>`:''}${action('choose-ingredients','Choose another ingredient','secondary')}<p class="tiny">Your guest will wait while you change things.</p></section>`;
}
function cupboard(c,summary){
 const editable=c.current?.stage==='plate';
 return `<section class="cafe-cupboard" aria-labelledby="cafe-cupboard-title"><div class="cafe-section-heading"><h2 id="cafe-cupboard-title">The cupboard</h2><a class="secondary" href="#orchard">Gather ingredients</a><p>${editable?'Tap a jar’s + to put one bite on your plate.':'Your recipe stays the same for this order.'}</p></div>${editable?`<div class="cafe-shelf-check"><span>${summary.count} of ${summary.order.bites} bites</span>${action('view-plate','See my plate','secondary')}${action('check','Check my plate','primary')}</div>`:''}<div class="cafe-jars">${availableIngredients(c).map(a=>{
  const n=c.current?.recipe[a.id]||0,full=summary&&summary.count>=summary.order.bites;
  return `<article class="cafe-jar"><div class="cafe-jar-body" style="--jar:${esc(a.color)}"><span class="cafe-jar-lid" aria-hidden="true"></span><div class="cafe-jar-label">${foodArt(a.id)}<h3>${esc(a.name)}</h3><div class="jar-qualities">${qualityIcons(a.properties)}</div><span class="cafe-jar-stock">${c.stock[a.id]} in the jar</span><a class="jar-gather-link" href="#orchard/gather/${a.id}">Find ${esc(a.name)}</a></div></div>${editable?`<div class="cafe-jar-controls"><button type="button" data-cafe-bite="${esc(a.id)}" data-cafe-delta="-1" aria-label="Remove ${esc(a.name)}" ${n===0?'disabled':''}>−</button><span aria-label="${plural(n,'bite')} on your plate">${n}</span><button type="button" data-cafe-bite="${esc(a.id)}" data-cafe-delta="1" aria-label="Add ${esc(a.name)}" ${full||n>=12?'disabled':''}>+</button></div>`:`<p class="cafe-fixed-count">${plural(n,'bite')} per plate</p>`}</article>`;
 }).join('')}</div>${editable?'<p class="tiny cafe-cupboard-note">You can plan with a bite even if its jar is low. Gather enough before serving.</p>':''}</section>`;
}
function plateFeedback(c,summary){
 const last=c.current.plateAttempts.at(-1);if(!last)return '';
 const same=ingredients.every(a=>last.recipe[a.id]===c.current.recipe[a.id]);
 if(!same)return '<p class="cafe-feedback" role="status">Your plate has changed. Check it when you’re ready.</p>';
 const count=last.count===summary.order.bites?'The number of bites fits.':`There ${last.count===1?'is':'are'} ${plural(last.count,'bite')}; the plate needs ${summary.order.bites}.`;
 const missing=last.missingProperties.length?` Still looking for: ${last.missingProperties.map(esc).join(' and ')}.`:' Both wishes are represented.';
 return `<p class="cafe-feedback" role="status">${count}${missing} You can change any bite and check again.</p>`;
}
function repairView(c,summary,q){
 const last=q.attempts.at(-1),message=last?(last.correct?(q.kind==='ingredient'?'That food supplies the missing quality. Go back and choose what to swap or add.':'That is the gap. Go back and change the bites on your plate.'):'Try another idea, ask for help, or go back to your plate.'):'';
 return `<section class="cafe-work cafe-repair" aria-labelledby="cafe-work-title"><p class="cafe-eyebrow">A question from our guest</p><h2 id="cafe-work-title" tabindex="-1">Let’s make it fit</h2><div class="cafe-repair-top">${action('repair-leave','Change my plate','primary')}<p class="tiny">You can change the ingredients now, or try this repair question first.</p></div>${plateView(c,summary.order)}<div class="cafe-wishes">${tags(summary.order.wanted)}</div><p class="question">${esc(q.prompt)}</p>${hearButton(q.prompt)}<div class="repair-choices ${q.kind==='count'?'repair-numbers':''}" role="group" aria-label="Repair choices">${q.kind==='ingredient'?q.choices.map(a=>`<button class="repair-food" data-cafe-repair="${a.id}">${foodArt(a.id)}<strong>${esc(a.name)}</strong>${qualityIcons(a.properties)}</button>`).join(''):Array.from({length:13},(_,i)=>`<button class="secondary repair-count" data-cafe-repair="${i}">${i}</button>`).join('')}</div>${message?`<p class="cafe-feedback" id="cafe-repair-feedback" tabindex="-1" role="status">${esc(message)}</p>`:''}${q.supported?`<p class="cafe-help" id="cafe-repair-hint" tabindex="-1">${q.kind==='ingredient'?`Look for the ${esc(q.target)} symbol. More than one food can work.`:`Compare ${summary.count} bites on the plate with ${summary.order.bites} needed. ${q.direction==='remove'?'Remove':'Add'} ${q.needed} to make the number fit.`}</p>`:''}<div class="cafe-controls">${action('repair-help','Help me look','secondary')}${action('repair-leave','Back to my plate','primary')}</div><p class="tiny">You can return to your plate before answering. This question helps us fix this order.</p></section>`;
}
function orderPictures(o){return `<div class="cafe-order-pictures" role="img" aria-label="${o.guests} guests; ${o.bites} bites on each plate"><div class="pictured-guests">${Array.from({length:o.guests},()=>'<svg viewBox="0 0 28 34" aria-hidden="true"><circle cx="14" cy="9" r="7" fill="#abc4da" stroke="#183f39"/><path d="M4 33v-9q0-10 10-10t10 10v9" fill="#b8d4c3" stroke="#183f39"/></svg>').join('')}</div><span>${plural(o.guests,'guest')}</span><div class="pictured-bites">${dots(o.bites,'#e9b84a')}</div><span>${plural(o.bites,'bite')} each</span></div>`;}
function cafeToolbar(c){return `<section class="cafe-trip-tools"><a class="primary" href="#orchard">✿ Explore and gather</a><a class="secondary" href="#facts">Explore the 12 × 12 garden</a><details><summary>Choose numbers for new orders</summary><div class="cafe-controls">${[['small','Small orders: 2–4 guests, 2–3 bites'],['all','All facts: 1–12 guests and bites']].map(([v,label])=>`<button class="secondary" data-cafe-range="${v}" aria-pressed="${c.range===v}">${label}</button>`).join('')}</div><p class="tiny">Your current guest keeps this order. The next guest uses the selected range.</p></details></section>`;}
function numberForm(d,label){
 return `${hearButton(label)}<form class="cafe-number-form" data-cafe-number-form novalidate><label for="cafe-answer">${label}</label><div class="cafe-answer-line"><input id="cafe-answer" type="text" inputmode="numeric" autocomplete="off" maxlength="3" value="${esc(d.input)}" aria-describedby="cafe-number-error"><button type="submit" class="primary">Check my number</button></div><p id="cafe-number-error" data-cafe-error role="alert"></p></form>`;
}
function totalSupport(x,order){
 const d=x.total;if(!d.supported)return '';
 const steps=Math.min(order.guests,Math.max(0,d.steps||0));
 return `<section class="cafe-help" aria-labelledby="cafe-help-title"><h3 id="cafe-help-title" tabindex="-1">One equal plate at a time</h3><p>There are ${order.guests} guests, with ${plural(order.bites,'bite')} for each guest.</p><div class="cafe-count-plates" role="img" aria-label="${order.guests} equal plates with ${order.bites} bites each; ${steps} plates counted">${Array.from({length:order.guests},(_,i)=>`<div class="cafe-count-plate ${i<steps?'counted':''}">${dots(order.bites,i<steps?'#e9b84a':'#b8d4c3')}</div>`).join('')}</div><p class="cafe-model-readout" aria-live="polite">${plural(steps,'plate')} counted: ${plural(steps*order.bites,'bite')}.</p><div class="cafe-controls">${action('step','Count the next plate','secondary',steps===order.guests?'disabled':'')}${action('recount','Count again','text-button')}</div>${d.revealed?`<p class="cafe-explanation">${order.guests} equal plates with ${plural(order.bites,'bite')} each: ${order.guests} × ${order.bites} = ${order.total} bites altogether.</p>`:action('explain','Show the equal-groups explanation','text-button')}<p class="tiny">This picture and explanation are support for your practice.</p></section>`;
}
function stockSupport(x,summary){
 const d=x.shortfall;if(!d.supported)return '';
 const steps=Math.min(summary.items.length,Math.max(0,d.steps||0)),counted=summary.items.slice(0,steps).reduce((sum,i)=>sum+i.missing,0);
 return `<section class="cafe-help" aria-labelledby="cafe-help-title"><h3 id="cafe-help-title" tabindex="-1">Check each jar’s gap</h3><p>Count only the extra bites needed. A jar with enough already needs zero extra.</p><ul class="cafe-gap-list">${summary.items.map((item,i)=>`<li class="${i<steps?'counted':''}"><strong>${esc(item.ingredient.name)}</strong><span class="cafe-gap-dots" role="img" aria-label="${item.required} needed: ${Math.min(item.stock,item.required)} already in the jar, ${item.missing} extra needed">${Array.from({length:item.required},(_,j)=>`<span class="cafe-gap-dot ${j>=item.stock?'missing':''}" aria-hidden="true"></span>`).join('')}</span><span>${i<steps?`${item.missing} extra needed`:'Not counted yet'}</span></li>`).join('')}</ul><p class="tiny">Green dots: already in the jar. Ringed yellow dots: extra needed.</p><p class="cafe-model-readout" aria-live="polite">${plural(steps,'jar')} counted: ${plural(counted,'extra bite')} so far.</p><div class="cafe-controls">${action('step','Count the next jar','secondary',steps===summary.items.length?'disabled':'')}${action('recount','Count again','text-button')}</div>${d.revealed?`<div class="cafe-explanation">${summary.items.map(i=>`<p>${esc(i.ingredient.name)}: ${i.stock>=i.required?`${i.stock} in stock covers ${i.required} needed, so 0 extra.`:`${i.required} needed − ${i.stock} in stock = ${i.missing} extra.`}</p>`).join('')}<p>Altogether, add ${plural(summary.missing,'bite')}.${summary.missing===0?' Every selected jar already has enough.':''}</p></div>`:action('explain','Show the cupboard explanation','text-button')}<p class="tiny">This picture and explanation are support for your practice.</p></section>`;
}
function stageView(c,summary){
 const x=c.current,o=summary.order,q=repairQuestion({cafe:c});
 if(x.stage==='plate'&&q)return repairView(c,summary,q);
 if(x.stage==='plate')return `<section class="cafe-work" aria-labelledby="cafe-work-title"><p class="cafe-eyebrow">Make one plate</p><h2 id="cafe-work-title" tabindex="-1">What will go together?</h2><p>Fill exactly ${plural(o.bites,'bite slot')}. Include something <strong>${esc(o.wanted[0])}</strong> and something <strong>${esc(o.wanted[1])}</strong>.</p><p class="cafe-rule">Different bites can supply the two wishes. One bite with both also works. You can repeat a bite.</p>${plateView(c,o)}<p class="cafe-plate-caption">${summary.count} of ${o.bites} bites chosen${summary.items.length?`: ${summary.items.map(i=>`${i.count} ${esc(i.ingredient.name)}`).join(', ')}`:''}.</p><div aria-live="polite">${plateFeedback(c,summary)}</div>${plateEditor(c,summary)}${action('check','Check this plate','primary')}</section>`;
 if(x.stage==='total')return `<section class="cafe-work" aria-labelledby="cafe-work-title"><p class="cafe-eyebrow">For the table</p><h2 id="cafe-work-title" tabindex="-1">One plate for each guest</h2>${action('revise-plate','Change my plate','secondary')}<p class="tiny">Your guest and numbers will wait. Your multiplication work stays here.</p><p>Your plate includes both wishes. There are <strong>${o.guests} guests</strong>, and each needs <strong>${plural(o.bites,'bite')}</strong>.</p>${numberForm(x.total,'How many bites are needed altogether?')}${x.total.attempts.length?'<p class="cafe-feedback" role="status">That number does not match this order yet. Try another number, count the plates, or leave the number for now.</p>':''}${!x.total.supported?action('help','Count the plates together','secondary'):''}${totalSupport(x,o)}<div class="cafe-stage-skip">${action('skip-stage','Leave this number for now','text-button')}<span class="tiny">The order can continue with support.</span></div></section>`;
 const plan=summary.plan,original={...summary,items:plan.items.map(i=>({...i,ingredient:ingredients.find(a=>a.id===i.ingredientId)})),missing:plan.missing};
 const ready=x.shortfall.skipped||x.shortfall.attempts.at(-1)===plan.missing,shortages=summary.items.filter(i=>i.missing>0);
 return `<section class="cafe-work" aria-labelledby="cafe-work-title"><p class="cafe-eyebrow">Check the cupboard</p><h2 id="cafe-work-title" tabindex="-1">Enough for everyone?</h2><p>The table needs ${plural(o.total,'bite')}. Each ingredient needs enough in its own jar.</p><div class="cafe-stock-table"><table><caption>Our original cupboard plan and the supplies now</caption><thead><tr><th scope="col">Ingredient</th><th scope="col">Need</th><th scope="col">At start</th><th scope="col">Now</th></tr></thead><tbody>${original.items.map(i=>`<tr><th scope="row">${esc(i.ingredient.name)}</th><td>${i.required}</td><td>${i.stock}</td><td>${c.stock[i.ingredientId]}</td></tr>`).join('')}</tbody></table></div>${shortages.length?`<section class="cafe-gather-list"><h3>A little gathering trip</h3><p>Your guest and recipe will wait. Bring back these foods:</p>${shortages.map(i=>`<a class="gather-needed" href="#orchard/gather/${i.ingredient.id}">${foodArt(i.ingredient.id)}<span><strong>${esc(i.ingredient.name)}</strong><span>${plural(i.missing,'more bite')} needed</span></span><span aria-hidden="true">→</span></a>`).join('')}</section>`:'<p class="cafe-feedback" role="status">The cupboard has enough real supplies for this order.</p>'}${ready?`<p class="cafe-feedback">${x.shortfall.skipped?'The planning number was left for now with help.':'That number fits our original plan.'} At the start, we needed ${plural(plan.missing,'extra bite')}.</p>${summary.ready?action('serve','Serve our guest','primary'):'<p>We can serve when the gathering is done. Answering the question does not fill the jars.</p>'}`:`${numberForm(x.shortfall,'At the start, how many extra bites did we need altogether?')}<p class="tiny">Use the At start column. Gathering changes the Now column; our original question stays the same.</p>${x.shortfall.attempts.length?'<p class="cafe-feedback">Let’s check the original gaps again, use the picture, or leave the number for now.</p>':''}`}${!x.shortfall.supported?action('help','Look at the original cupboard gaps','secondary'):''}${stockSupport(x,original)}${!ready?`<div class="cafe-stage-skip">${action('skip-stage','Leave this number for now','text-button')}<span class="tiny">We still need to gather the supplies before serving.</span></div>`:''}</section>`;
}
export function renderCafe(state){
 const c=state.cafe,x=c?.current,summary=x?cafeSummary(state):null;
 const opening=`<header class="cafe-heading"><a class="back" href="#home">← Pause in the garden</a><p class="cafe-eyebrow">Open for make-believe</p><h1>The Almost-Right Café</h1><p>Imaginary guests. Impossible ingredients. A warm welcome after the storm.</p></header><details class="cafe-howto" ${!c.current&&!c.history.length?'open':''}><summary>Why we’re here &amp; how to play</summary><p>The storm has passed, and our neighbors are safe. Some have stopped by for a meal while we help the garden feel like home again. Their favorite dishes are sold out—but your ideas can make something just as lovely.</p>${hearButton('The storm has passed, and our neighbors are safe. Some have stopped by for a meal while we help the garden feel like home again. Their favorite dishes are sold out, but your ideas can make something just as lovely. First, look at the order. Find the two food wishes and how many bites belong on each plate. Next, tap the jars to make one plate. Different mixtures can work. Then count enough for the whole table. If a jar is short, explore the orchard, find that food, and bring back a harvest. Your guest will wait. When there is enough in every jar, serve your guest. Pictures and help are always welcome.','Hear our café story')}<ol class="cafe-howto-steps"><li><span aria-hidden="true">✉</span><div><strong>Look at the order.</strong><p>Find the two food wishes and the number of bites for each plate.</p></div></li><li><span aria-hidden="true">＋</span><div><strong>Make a plate.</strong><p>Tap the jars to try a mixture. Then count enough for the whole table.</p></div></li><li><span aria-hidden="true">✿</span><div><strong>Gather, then serve.</strong><p>Jar running low? Find that food in the orchard and bring back a harvest. Your guest and plate will wait.</p></div></li></ol><p class="tiny">Pictures, help, and breaks are always welcome. Every guest can wait. <a href="#home">Read the garden’s beginning</a></p></details>`;
 if(!summary)return `<div data-cafe-view class="cafe-game">${opening}${supperPanel(c)}${cafeToolbar(c)}<section class="cafe-work"><h2 id="cafe-work-title" tabindex="-1">The counter is resting</h2><p>Invite a make-believe guest whenever you like.</p>${action('next','Invite a guest','primary')}<a class="secondary" href="#orchard">Gather ingredients</a></section></div>`;
 const o=summary.order,served=x.stage==='served';
 const response=served?`<section class="cafe-work cafe-response"><p class="cafe-eyebrow">A place to pause</p><h2 id="cafe-work-title" tabindex="-1">${x.recovered?'This saved visit is closed':'Thank you from '+esc(o.guest.name)}</h2><p>${x.recovered?'This saved order stays closed. You can invite another guest when you like.':esc(o.guest.thanks)}</p>${!x.recovered?plateView(c,o):''}<div class="cafe-controls">${action('next','Invite the next guest','primary')}<a class="secondary" href="#orchard">Gather ingredients</a></div><p class="tiny">Explore the orchard when the cupboard needs more ingredients, or leave the café here.</p></section>`:stageView(c,summary);
 return `<div data-cafe-view class="cafe-game">${opening}${supperPanel(c)}${cafeToolbar(c)}<div class="cafe-counter-scene"><aside class="cafe-guest">${guestArt(o.guest)}<h2>${esc(o.guest.name)}</h2><p>${esc(served?'Your make-believe guest at the counter.':o.guest.greeting)}</p></aside><aside class="cafe-ticket" aria-label="The current order"><p class="cafe-ticket-top">ALMOST-RIGHT CAFÉ<br><span>One order, many possibilities</span></p><p>“${esc(o.guest.wantedDish)}” is sold out.</p><p>Instead, include something:</p><div class="cafe-wishes">${tags(o.wanted)}</div>${orderPictures(o)}${hearButton(`${o.guest.name} would like something ${o.wanted.join(' and ')}. There are ${o.guests} guests, with ${o.bites} bites each.`,'Hear the order')}<dl><div><dt>Guests</dt><dd>${o.guests}</dd></div><div><dt>Bites per plate</dt><dd>${o.bites}</dd></div></dl><p class="tiny">${served?'A closed order.':'One bite is one unit from a jar. All food and guests are pretend.'}</p></aside>${response}</div>${cupboard(c,summary)}<footer class="cafe-footer">${!served?action('skip-guest','Let this guest wait; invite another','secondary'):''}<a class="text-button" href="#home">Pause in the garden</a><p class="tiny">This is practice. Pictures, explanations, and leaving a number for now are welcome. There are no grades.</p><div class="cafe-story-invite"><span>Curious how Pip and Dot opened the café?</span><button type="button" class="text-button" data-start-path="cafe">Visit the introductory café story</button></div></footer></div>`;
}
function numberNote(label,d){
 return `<p><strong>${label}:</strong> ${d.attempts.length?'Answers tried: '+d.attempts.map(esc).join(', ')+'.':'No answer tried.'} ${d.skipped?'Number left for now with support. ':''}${d.supported?'Support used. ':'No support recorded. '}${d.steps?plural(d.steps,'picture step')+' counted. ':''}${d.revealed?'Explanation opened.':''}</p>`;
}
function repairNote(x){const list=[...(x.repairHistory||[]),...(x.repair?[x.repair]:[])];return list.length?`<p><strong>Repair questions:</strong> ${list.length} guided questions; ${list.reduce((n,r)=>n+r.attempts.length,0)} responses; ${list.some(r=>r.supported)?'help used':'no help recorded'}. These do not establish fact recall.</p>`:'';}
function recordNote(c,r){
 const o=orderFor(c,r.orderIndex),recipe=ingredients.filter(a=>r.recipe[a.id]>0),missing=recipe.reduce((sum,a)=>sum+Math.max(0,r.recipe[a.id]*o.guests-r.stockBefore[a.id]),0);
 return `<details class="cafe-order-note"><summary>${esc(o.guest.name)} · ${r.status==='served'?'Served':'Guest left waiting'}</summary><p>Wishes: ${o.wanted.map(esc).join(' and ')}. ${plural(o.guests,'guest')}; ${plural(o.bites,'bite')} per plate.</p><p>Plate: ${recipe.length?recipe.map(a=>`${r.recipe[a.id]} ${esc(a.name)}`).join(', '):'No bites selected'}.</p><p><strong>Plate checks:</strong> ${r.plateAttempts.length?`${r.plateAttempts.length} recorded.`:'None recorded.'}</p>${r.plateAttempts.length?`<ul>${r.plateAttempts.map((a,i)=>`<li>Check ${i+1}: ${plural(a.count,'bite')}; ${a.valid?'both wishes and bite count fit':`${a.missingProperties.length?'missing '+a.missingProperties.map(esc).join(' and ')+'; ':''}${a.count===o.bites?'bite count fits':'bite count does not fit'}`}.</li>`).join('')}</ul>`:''}${repairNote(r)}${numberNote('For the table',r.total)}${numberNote('Cupboard shortfall',r.shortfall)}<p class="tiny">Table target: ${plural(o.total,'bite')}. Cupboard gap at this order: ${plural(missing,'bite')}. ${r.status==='skipped'?'This guest’s order changed no stock.':r.cupboardPlan?'Gathered supplies were used once. The gap refers to the original plan.':'This older order used the previous automatic top-up rule.'}</p></details>`;
}
export function cafeNotes(state){
 const c=state.cafe;if(!c)return '<section class="panel cafe-notebook"><h2>Café practice</h2><p>No café orders yet.</p><a href="#cafe">Visit the café</a></section>';
 const x=c.current,o=x?orderFor(c):null,waiting=x&&x.stage!=='served';
 return `<section class="panel cafe-notebook"><h2>Café practice</h2><p>All café play is practice. Plate checks, arithmetic attempts, skips, and support are recorded separately. No mastery, general level, empathy, or independent reading is inferred.</p><p><strong>Café story:</strong> ${cafeSupper(c).round===1?'Welcome-back dinner':'New Game Plus '+(cafeSupper(c).round-1)} · ${cafeSupper(c).progress} of 6 tables served${cafeSupper(c).complete?' · Goal complete':''}. Story progress counts served orders, including orders with help; it is separate from mathematical evidence.</p><p>Orchard discoveries: ${c.discoveries?.length||0} of 3. Discoveries record pretend play, not scientific or food knowledge.</p>${waiting?`<div class="cafe-waiting-note"><h3>A guest is waiting: ${esc(o.guest.name)}</h3><p>Current step: ${esc({plate:'make a plate',total:'bites for the table',stock:'cupboard shortfall'}[x.stage]||'preparing')}.</p><p>${x.plateAttempts.length} plate checks recorded so far.</p>${repairNote(x)}${numberNote('For the table',x.total)}${numberNote('Cupboard shortfall',x.shortfall)}<a href="#cafe">Continue this order</a></div>`:x?.recovered?'<p>A recovered saved visit is closed and cannot spend stock again.</p>':''}<p class="tiny">${c.served} served orders in this browser. The latest ${c.history.length} served or skipped orders are listed below, up to 24. These counts describe play, not achievement.</p>${[...c.history].reverse().map(r=>recordNote(c,r)).join('')||'<p>No served or skipped orders yet.</p>'}<a href="#cafe">Return to the café</a></section>`;
}
export function bindCafe(state,{save,render,exposeFacts,focus}){
 const view=document.querySelector('[data-cafe-view]');if(!view)return;
 const reveal=(selector,fallback)=>{const target=document.querySelector(selector)?selector:fallback||selector;focus(target);document.querySelector(target)?.scrollIntoView({block:['#cafe-plate-editor-title','#cafe-cupboard-title'].includes(target)?'start':'nearest',behavior:'auto'});};
 const redraw=(selector,fallback)=>{save();render();if(selector)reveal(selector,fallback);};
 view.querySelectorAll('[data-cafe-bite]').forEach(button=>button.addEventListener('click',()=>{
  adjustBite(state,button.dataset.cafeBite,Number(button.dataset.cafeDelta));
  // Keep the same jar reachable even when its add/remove button has just become disabled.
  redraw(`[data-cafe-bite="${button.dataset.cafeBite}"][data-cafe-delta="${button.dataset.cafeDelta}"]:not(:disabled)`,`[data-cafe-bite="${button.dataset.cafeBite}"]:not(:disabled)`);
 }));
 view.querySelectorAll('[data-cafe-plate-remove]').forEach(button=>button.addEventListener('click',()=>{
  if(!adjustBite(state,button.dataset.cafePlateRemove,-1))return;
  redraw(`[data-cafe-plate-remove="${button.dataset.cafePlateRemove}"]`,'#cafe-plate-editor-title');
 }));
 view.querySelectorAll('[data-cafe-range]').forEach(b=>b.addEventListener('click',()=>{setCafeRange(state,b.dataset.cafeRange);redraw(`[data-cafe-range="${b.dataset.cafeRange}"]`);}));
 view.querySelectorAll('[data-cafe-repair]').forEach(b=>b.addEventListener('click',()=>{const q=repairQuestion(state);if(!q)return;const correct=answerRepair(state,q.kind==='count'?Number(b.dataset.cafeRepair):b.dataset.cafeRepair);if(correct)leaveRepair(state);redraw(correct?'#cafe-plate-editor-title':'#cafe-repair-feedback');}));
 const input=view.querySelector('#cafe-answer');
 input?.addEventListener('input',()=>{const x=state.cafe.current;if(!x||!['total','stock'].includes(x.stage))return;(x.stage==='total'?x.total:x.shortfall).input=input.value.slice(0,3);save();});
 view.querySelector('[data-cafe-number-form]')?.addEventListener('submit',event=>{
  event.preventDefault();const value=numericAnswer(input.value);
  if(!Number.isSafeInteger(value)||value<0||value>999){view.querySelector('[data-cafe-error]').textContent='Use a whole number from 0 to 999.';input.focus();return;}
  const stage=state.cafe.current.stage,correct=submitCafeNumber(state,value);if(!correct){supportCafe(state);const d=stage==='total'?state.cafe.current.total:state.cafe.current.shortfall;d.steps=Math.max(1,d.steps);if(stage==='total'){const o=orderFor(state.cafe);exposeFacts([[o.guests,o.bites]]);}}
  redraw(state.cafe.current.stage!==stage||correct?'#cafe-work-title':'#cafe-answer');
 });
 view.querySelectorAll('[data-cafe-action]').forEach(button=>button.addEventListener('click',()=>{
  const id=button.dataset.cafeAction;
  if(id==='new-game-plus'){if(beginCafePlus(state))redraw('#cafe-work-title');return;}
  if(id==='continue-cafe'){if(!state.cafe.current||state.cafe.current.stage==='served')nextGuest(state);redraw('#cafe-work-title');return;}
  if(id==='revise-plate'){if(reviseCafePlate(state))redraw('#cafe-plate-editor-title');return;}
  if(id==='choose-ingredients'||id==='view-plate'){reveal(id==='view-plate'?'#cafe-plate-editor-title':'#cafe-cupboard-title');return;}
  if(id==='repair-help'||id==='repair-leave'){(id==='repair-help'?helpRepair:leaveRepair)(state);redraw(id==='repair-leave'?'#cafe-plate-editor-title':'#cafe-repair-hint');return;}
  if(['help','step','recount','explain'].includes(id)){
   const c=ensureCafe(state),x=c.current;if(!x||!['total','stock'].includes(x.stage))return;
   const o=orderFor(c),d=x.stage==='total'?x.total:x.shortfall,limit=x.stage==='total'?o.guests:currentRecipe(c).length;
   if(id==='help'||id==='step')d.steps=Math.min(limit,Math.max(0,d.steps||0)+1);
   if(id==='recount')d.steps=0;
   if(id==='explain')d.revealed=true;
   supportCafe(state);if(x.stage==='total')exposeFacts([[o.guests,o.bites]]);
   redraw('#cafe-help-title');return;
  }
  const actions={check:checkPlate,'skip-stage':skipCafeStage,serve:serveCafe,next:nextGuest,'skip-guest':skipGuest};
  if(actions[id]){const wasComplete=cafeSupper(state.cafe).complete;actions[id](state);redraw(id==='serve'&&!wasComplete&&cafeSupper(state.cafe).complete?'#cafe-supper-title':id==='check'&&state.cafe.current.stage==='plate'&&!repairQuestion(state)?'[data-cafe-action="check"]':'#cafe-work-title');}
 }));
}
